mapper.select:
SELECT id, city, aqi_value AS aqiValue, quality_level AS qualityLevel, date, create_time AS createTime FROM aqi_data
AND city LIKE CONCAT('%', #{dto.city}, '%')
AND date >= #{dto.startDate}
AND date <= #{dto.endDate}
ORDER BY date DESC, aqi_value ASC

SELECT DATE_FORMAT(date, '%Y-%m-%d') AS date, aqi_value AS aqiValue
FROM aqi_data
WHERE city = #{city}
ORDER BY date DESC
LIMIT #{days}

SELECT quality_level AS name, COUNT(*) AS value
FROM aqi_data


        AND city = #{city}


        AND date >= #{startDate}


        AND date <= #{endDate}


GROUP BY quality_level
ORDER BY value DESC

SELECT city, aqi_value AS aqiValue, quality_level AS qualityLevel, DATE_FORMAT(date, '%Y-%m-%d') AS date FROM aqi_data WHERE date = COALESCE(NULLIF(#{date}, ''), (SELECT MAX(date) FROM aqi_data)) AND city IN
#{city}
ORDER BY aqi_value ASC
